import{_ as t,o,c as n,ag as a}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"FunctionDeployment — takoform_function_deployment","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/function/function-deployment.md","filePath":"proposals/function/function-deployment.md"}'),i={name:"proposals/function/function-deployment.md"};function r(s,e,l,d,c,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="functiondeployment-—-takoform-function-deployment" tabindex="-1">FunctionDeployment — <code>takoform_function_deployment</code> <a class="header-anchor" href="#functiondeployment-—-takoform-function-deployment" aria-label="Permalink to &quot;FunctionDeployment — `takoform_function_deployment`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>An operator moves traffic between Function Versions of one Function: shift a share of invocations to a candidate version, promote it, or roll back — all by re-weighting, never by mutating a revision.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>deployment</code>. This is the only mutable path for traffic movement.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>function</code> is the immutable reference naming the Function this deployment governs, and every listed version MUST belong to it: an entry whose version resolves to a different function&#39;s aggregate is <code>invalid_argument</code> before any mutation, decided against resolved UIDs, never names — the Edge family&#39;s deployment-integrity rule verbatim. At most one deployment governs one function incarnation.</p><p><code>versions</code> lists one or two entries of <code>functionVersion</code> plus <code>weight</code> in basis points. Every weight is positive — a zero-weight entry is not a smaller split but a version the deployment does not select, and the Edge family&#39;s <code>WorkerDeployment</code> already refuses it — and weights must sum to exactly 10000 across entries; the sum is host-validated semantics because a JSON schema cannot add weights. A single-version deployment is one entry at 10000. Each invocation is served entirely by one selected version; a caller never observes a blend of two versions within one invocation.</p><p>Two entries, not eight: the proven regional function service shifts traffic between one stable version and one candidate, and this family preserves that shape rather than importing the Edge family&#39;s eight-way split. A wider split would be a new exact version of this Form, argued from the shape it preserves.</p><p>A Function has at most one FunctionDeployment. Attachments are admitted against the deployment and refused when it is absent; deleting the deployment while an attachment lives is refused; and the identity reports Ready only while its deployment serves — the family&#39;s aggregate statement, mirroring <a href="./../../spec/decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Version selection is a single atomic fact per function. Splitting weights across resources would allow interleavings in which the observable sum is temporarily wrong.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Named multi-alias routing — several concurrently addressable version mixes per function — is a different shape: this family&#39;s attachments resolve through THE active deployment. Per-request routing rules and session pinning carry different selection semantics and are separate work.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None; the deployment selects revisions, it does not use capabilities.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>A deployment referencing a deleted or absent version must fail closed (<code>resource_not_found</code>, and dependency protection keeps a weighted version undeletable). Rollback is re-weighting to a previous version and must not require recreating it. Deleting the deployment stops traffic selection but never deletes the function or its versions, and is refused with <code>dependency_in_use</code> while an attachment lives.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The weighted alias of a proven cloud function service, reduced to its portable core: exact basis-point weights over immutable versions, one active selection per function.</p>',22)])])}const u=t(i,[["render",r]]);export{p as __pageData,u as default};
